Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MAXN = (1 << 19) + 5;
int n, k, mod, maxN, popcount_arr[MAXN], f[MAXN];
int t1[20][MAXN], t2[20][MAXN], t3[20][MAXN];
long long mod2;
long long tmp_arr[20][MAXN];
long long fact[MAXN], inv_fact[MAXN];

long long binpow(long long a, long long b) {
    long long res = 1;
    a %= mod;
    while (b) {
        if (b & 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b >>= 1;
    }
    return res;
}

void init() {
    fact[0] = 1;
    for (int i = 1; i <= maxN; ++i)
        fact[i] = fact[i-1] * i % mod;
    inv_fact[maxN] = binpow(fact[maxN], mod - 2);
    for (int i = maxN - 1; i >= 0; --i)
        inv_fact[i] = inv_fact[i+1] * (i+1) % mod;
}

int next_pow2(int x) {
    int p = 1;
    while (p < x) p <<= 1;
    return p;
}

void fwht(int *a, int len, bool inv = false) {
    static long long buf[MAXN];
    for (int i = 0; i < len; ++i) buf[i] = a[i];

    if (inv) {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    buf[i + j + step] = (buf[i + j] - buf[i + j + step] + mod) % mod;
                }
            }
        }
    } else {
        for (int step = 1; step < len; step <<= 1) {
            for (int i = 0; i < len; i += step << 1) {
                for (int j = 0; j < step; ++j) {
                    buf[i + j + step] = (buf[i + j] + buf[i + j + step]) % mod;
                }
            }
        }
    }

    for (int i = 0; i < len; ++i) {
        a[i] = (int)(buf[i] % mod);
        if (a[i] < 0) a[i] += mod;
    }
}

inline void mod_reduce(long long &x) {
    if (x >= mod2) x -= mod2;
}

void multiply_arrays() {
    for (int i = 0; i <= 19; ++i) {
        memset(t1[i], 0, sizeof(int[maxN + 1]));
        memset(tmp_arr[i], 0, sizeof(long long[maxN + 1]));
    }

    for (int i = 0; i <= maxN; ++i)
        t1[popcount_arr[i]][i] = f[i];

    for (int i = 0; i <= 19; ++i)
        fwht(t1[i], maxN + 1);

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= maxN; ++s)
                mod_reduce(tmp_arr[q + l][s] += 1LL * t1[q][s] * t2[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= maxN; ++s)
            t3[q][s] = (int)(tmp_arr[q][s] % mod);

    for (int i = 0; i <= 19; ++i)
        fwht(t3[i], maxN + 1, true);

    for (int i = 0; i <= maxN; ++i)
        f[i] = t3[popcount_arr[i]][i];
}

void square_arrays() {
    static int temp[20][MAXN];
    for (int i = 0; i <= 19; ++i)
        memset(tmp_arr[i], 0, sizeof(long long[maxN + 1]));

    for (int q = 0; q <= 19; ++q)
        for (int l = 0; q + l <= 19; ++l)
            for (int s = 0; s <= maxN; ++s)
                mod_reduce(tmp_arr[q + l][s] += 1LL * t2[q][s] * t2[l][s]);

    for (int q = 0; q <= 19; ++q)
        for (int s = 0; s <= maxN; ++s)
            temp[q][s] = (int)(tmp_arr[q][s] % mod);

    for (int i = 0; i <= 19; ++i)
        fwht(temp[i], maxN + 1, true);

    for (int i = 0; i <= 19; ++i)
        memset(t2[i], 0, sizeof(int[maxN + 1]));

    for (int i = 0; i <= maxN; ++i)
        t2[popcount_arr[i]][i] = temp[popcount_arr[i]][i];

    for (int i = 0; i <= 19; ++i)
        fwht(t2[i], maxN + 1);
}

int main() {
    scanf("%d%d%d", &n, &k, &mod);
    mod2 = 1LL * mod * mod;

    if (n & 1) {
        printf("%lld", binpow(k, n));
        return 0;
    }

    f[0] = 1;
    maxN = next_pow2(n + 1) - 1;
    init();

    for (int i = 0; i <= maxN; ++i)
        popcount_arr[i] = __builtin_popcount(i);

    for (int i = 0; i <= maxN; ++i)
        t2[popcount_arr[i]][i] = inv_fact[i];

    for (int i = 0; i <= 19; ++i)
        fwht(t2[i], maxN + 1);

    int orig_k = k;
    while (k) {
        if (k & 1) multiply_arrays();
        k >>= 1;
        if (k) square_arrays();
    }

    printf("%lld", (binpow(orig_k, n) - fact[n] * f[n] % mod + mod) % mod);
    return 0;
}
